import numpy as np


def r(x):
    # Maps x in [0, 1] to [0, 1] such that r(x) >= x, strictly greater for x in (0, 1)
    x_f = float(x)
    return 2.0 * x_f - x_f**2


def R(y_orig, y_new):
    # Ensure outputs are finite and monotonically increasing
    return np.isfinite(y_orig) and np.isfinite(y_new) and (y_new >= y_orig)
